package blockquotes

import "testing"

func TestResolveGitHubAlertCase(t *testing.T) {
	for _, s := range []string{"[!note]", "[!Note]", "[!nOtE]", "[!NOTE]"} {
		if got := resolveGitHubAlert("<p>" + s + "\n"); got != "note" {
			t.Errorf("%s: got %q", s, got)
		}
	}
	if got := resolveGitHubAlert("<p>[!nope]\n"); got != "" {
		t.Errorf("unexpected: %q", got)
	}
}
EOF
